import{_ as a,o as e,c as s,ai as n}from"./chunks/framework.BBSijY9B.js";const m=JSON.parse('{"title":"管理者","description":"团队负责人如何用 Grok Bot 掌握进度、准备会议、跟进待办，把时间留给决策。","frontmatter":{"related":["/templates/meeting-assistant","/templates/weekly-report","/templates/team-ops-weekly"],"title":"管理者","description":"团队负责人如何用 Grok Bot 掌握进度、准备会议、跟进待办，把时间留给决策。","section":"roles","order":1,"tags":["角色","管理者","会议","周报"],"sources":["https://cursor.com/docs/grok-bot/work","https://docs.x.ai/grok-bot/skills-routines-and-automations"],"wordCount":303,"readingTime":1,"head":[["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"管理者 | 王宇宙 | WANGXXXL"}],["meta",{"property":"og:description","content":"团队负责人如何用 Grok Bot 掌握进度、准备会议、跟进待办，把时间留给决策。"}],["meta",{"property":"og:url","content":"https://wangxxxl.com/roles/managers"}],["meta",{"property":"og:image","content":"https://wangxxxl.com/og/roles-managers-b2061bc4da.png"}],["meta",{"property":"og:image:alt","content":"管理者 · 王宇宙 | WANGXXXL · wangxxxl.com"}],["meta",{"name":"twitter:title","content":"管理者 | 王宇宙 | WANGXXXL"}],["meta",{"name":"twitter:description","content":"团队负责人如何用 Grok Bot 掌握进度、准备会议、跟进待办，把时间留给决策。"}],["meta",{"name":"twitter:image","content":"https://wangxxxl.com/og/roles-managers-b2061bc4da.png"}],["meta",{"name":"twitter:image:alt","content":"管理者 · 王宇宙 | WANGXXXL · wangxxxl.com"}],["link",{"rel":"canonical","href":"https://wangxxxl.com/roles/managers"}]]},"headers":[],"relativePath":"roles/managers.md","filePath":"roles/managers.md","lastUpdated":1792485206000}'),o={name:"roles/managers.md"};function i(l,t,p,r,c,d){return e(),s("div",null,[...t[0]||(t[0]=[n(`<h1 id="管理者" tabindex="-1">管理者 <a class="header-anchor" href="#管理者" aria-label="Permalink to &quot;管理者&quot;">​</a></h1><p>管理者的时间最容易被碎片信息吃掉：几十封邮件、几个群、几个项目看板，每样都要看一眼。Grok Bot 最适合替你做&quot;汇总、提醒、起草&quot;，把决定权留给你。</p><h2 id="典型工作" tabindex="-1">典型工作 <a class="header-anchor" href="#典型工作" aria-label="Permalink to &quot;典型工作&quot;">​</a></h2><ul><li>每天/每周汇总各项目进展，标出风险。</li><li>会前准备：议程、背景材料、上次会议的遗留事项。</li><li>会后整理：纪要、待办分派、跟进提醒。</li><li>起草对内通知、对外回复，你审核后发出。</li></ul><h2 id="示例提示词" tabindex="-1">示例提示词 <a class="header-anchor" href="#示例提示词" aria-label="Permalink to &quot;示例提示词&quot;">​</a></h2><p><strong>项目进度汇总</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>汇总这三个项目本周的进展：来源是项目看板、相关邮件和 Slack 的 #项目A/#项目B/#项目C 频道。</span></span>
<span class="line"><span>每个项目写：本周完成、正在卡住的事、需要我拍板的事。卡住超过 3 天的标红。</span></span></code></pre></div><p><strong>会前准备</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>明天上午 10 点和合作方开会。帮我准备一页简报：</span></span>
<span class="line"><span>对方公司近况（公开信息）、我们之间最近三个月的邮件往来要点、</span></span>
<span class="line"><span>上次会议承诺的事项及完成情况、建议我这次重点谈的 3 个问题。</span></span></code></pre></div><p><strong>会后整理</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>附件是会议录音。整理成纪要：决议、待办（负责人 + 截止日期）、待定问题。</span></span>
<span class="line"><span>再给每位负责人起草一封简短的跟进邮件，都放成草稿，我确认后再发。</span></span></code></pre></div><p><strong>一对一谈话准备</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>下周要和团队成员做一对一。根据他最近一个月在看板上的任务记录，</span></span>
<span class="line"><span>整理他做得好的地方和可能遇到的困难，各 3 条，作为我的谈话提纲。只给我看。</span></span></code></pre></div><h2 id="推荐例程" tabindex="-1">推荐例程 <a class="header-anchor" href="#推荐例程" aria-label="Permalink to &quot;推荐例程&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>每周五下午 4 点，运行&quot;周度团队汇总&quot;：</span></span>
<span class="line"><span>汇总各项目本周进展和下周计划，列出需要我决定的事项和逾期待办。</span></span>
<span class="line"><span>发在这个对话里，不要发给团队成员。</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">先让它&quot;只汇报&quot;</p><p>前几周只让 Bot 汇总和起草，不让它直接给团队发任何东西。等格式和判断稳定了，再考虑让它发内部提醒（仍然建议走草稿）。</p></div><div class="warning custom-block"><p class="custom-block-title">常见坑</p><ul><li><strong>把人事敏感信息放在共享电脑上</strong>：所有 Bot 都能看到，评估类材料用完即删。</li><li><strong>只看 Bot 的总结不看原始数据</strong>：重要决策前，让它附上来源链接，你抽查一两条。</li><li><strong>让 Bot 代你表态</strong>：涉及承诺、考核、预算的话，务必你自己说。</li></ul></div>`,17)])])}const h=a(o,[["render",i]]);export{m as __pageData,h as default};
